package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SchedRec struct {
	ScAcct  string
	ScPrin  decimal.Decimal
	ScRate  decimal.Decimal
	ScYears int64
}

var WsEofFlag string = "N"
var WsBal decimal.Decimal = decimal.NewFromInt(0)
var WsYear int64 = 0
var WsCount int64 = 0
var WsBalEd string = ""

var curRec SchedRec
var schedFile *os.File
var schedReader *bufio.Scanner
var schedEOF bool = false
var inputDone bool = false

func formatIntPic(width int, v int64) string {
	mod := int64(1)
	for i := 0; i < width; i++ {
		mod *= 10
	}
	// COBOL: keep low-order digits, handle negative by truncating magnitude then reapply sign
	// For our usage values are non-negative.
	if v < 0 {
		av := -v
		av = av % mod
		v = -av
		if v < 0 {
			// need zero padding with sign? Not needed for this program.
			// Simple handling: produce with minus sign
			s := fmt.Sprintf("%0*d", width, -v)
			if len(s) > width {
				s = s[len(s)-width:]
			}
			return "-" + s[1:] // not used
		}
	} else {
		v = v % mod
	}
	return fmt.Sprintf("%0*d", width, v)
}

func storeBal(v decimal.Decimal) decimal.Decimal {
	// enforce PIC 9(8)V99 : scale 2, integer 8 digits, truncation (already rounded/truncated before)
	// Keep low-order digits that fit.
	// v is expected to have scale <=2 after Round/Truncate.
	// Extract integer and fractional parts.
	// Use Truncate to get integer part toward zero.
	intPart := v.Truncate(0) // integer portion
	frac := v.Sub(intPart)   // fractional, may be negative

	// For negative, adjust to keep sign
	// Compute modulus for integer part: 10^8
	mod := decimal.NewFromInt(100000000) // 10^8
	// Need low-order 8 digits of integer part
	// intPart % mod keeping sign
	// decimal.Mod not available; use Div + Truncate
	// Use integer arithmetic via IntPart
	// Simpler: convert intPart to int64 if fits, but intPart may exceed int64? max 99,999,999 fits.
	// Use decimal division truncated toward zero.
	q := intPart.Div(mod).Truncate(0)
	intMod := intPart.Sub(q.Mul(mod))

	// Recombine
	result := intMod.Add(frac)
	// Ensure scale 2 truncation (should already be)
	// Normalize to exactly 2 decimal places truncated toward zero
	result = result.Truncate(2)
	return result
}

func formatBalEd(v decimal.Decimal) string {
	// PIC ZZ,ZZZ,ZZ9.99  len 13, integer 8 digits, 2 decimals
	// Ensure value is truncated to 2 decimals and high digits dropped already
	// But we redo high-digit dropping for formatting if needed (spec: if more integer digits than picture, high dropped)
	// Here WsBal already limited to 8 integer digits, so formatting just needs Z suppression.

	// Work with absolute value? Balances are positive.
	sign := ""
	if v.Sign() < 0 {
		sign = "-" // not expected, but handle
		v = v.Abs()
	}
	// Ensure scale 2
	v = v.Truncate(2)
	// Get integer and fractional
	intPart := v.Truncate(0)
	fracPart := v.Sub(intPart).Abs()

	// integer modulo 10^8 for high-digit drop
	mod := decimal.NewFromInt(100000000)
	q := intPart.Div(mod).Truncate(0)
	intMod := intPart.Sub(q.Mul(mod))
	intVal := intMod.IntPart() // 0 .. 99999999
	if intVal < 0 {
		intVal = -intVal
	}
	// fractional 0..99
	// Multiply fracPart by 100 truncated
	fracDecimal := fracPart.Mul(decimal.NewFromInt(100)).Truncate(0)
	fracVal := fracDecimal.IntPart()
	if fracVal < 0 {
		fracVal = -fracVal
	}

	// Build 8 digit string zero padded
	intStr := fmt.Sprintf("%08d", intVal) // d7..d0
	digits := []byte(intStr)              // length 8

	// Picture layout: digits 0,1 , 2,3,4 , 5,6,7
	// We'll build array of 10 chars for integer part including commas
	// positions: 0:d0,1:d1,2:',',3:d2,4:d3,5:d4,6:',',7:d5,8:d6,9:d7 ??? Let's map left to right
	// Use left to right order as described: d7 d6 , d5 d4 d3 , d2 d1 d0
	// So index mapping:
	// out0 = d7, out1 = d6, out2 = ',', out3 = d5, out4 = d4, out5 = d3, out6 = ',', out7 = d2, out8 = d1, out9 = d0

	// Determine suppression
	// For each digit position i 0..7, if picture char is Z and prefix all zero and we haven't hit non-zero, blank.
	outDigits := make([]byte, 8)
	suppressing := true
	for i := 0; i < 8; i++ {
		d := digits[i]
		isNine := (i == 7) // last digit is 9, all others Z
		if suppressing {
			if d == '0' && !isNine {
				// look ahead: if any later non-zero digit before end? Actually COBOL suppresses leading zeros regardless of later non-zero? No, suppression stops at first non-zero.
				// So if current is zero and we are suppressing, we blank unless this is the 9 position
				// Check if all remaining? No, we blank now, continue suppressing
				outDigits[i] = ' '
			} else if d == '0' && isNine {
				// 9 position: show 0
				outDigits[i] = '0'
				// suppression ends (or not needed)
			} else {
				// non-zero
				outDigits[i] = d
				suppressing = false
			}
		} else {
			outDigits[i] = d
		}
	}

	// Build integer formatted with commas
	// outInt length 10
	outInt := make([]byte, 10)
	outInt[0] = outDigits[0]
	outInt[1] = outDigits[1]
	outInt[2] = ','
	outInt[3] = outDigits[2]
	outInt[4] = outDigits[3]
	outInt[5] = outDigits[4]
	outInt[6] = ','
	outInt[7] = outDigits[5]
	outInt[8] = outDigits[6]
	outInt[9] = outDigits[7]

	// Replace commas inside suppressed zone with spaces
	// Comma is suppressed if all digits to its left are spaces
	// Check comma at outInt[2]: left digits outDigits[0], outDigits[1]
	if outDigits[0] == ' ' && outDigits[1] == ' ' {
		outInt[2] = ' '
	}
	// Comma at outInt[6]: left digits outDigits[0..4]
	leftAllSpace := true
	for k := 0; k < 5; k++ {
		if outDigits[k] != ' ' {
			leftAllSpace = false
			break
		}
	}
	if leftAllSpace {
		outInt[6] = ' '
	}

	fracStr := fmt.Sprintf("%02d", fracVal)

	result := string(outInt) + "." + fracStr
	if sign != "" {
		// COBOL would show sign; not needed for test, but prepend
		// Need to fit in width: just prefix
		result = sign + result[1:]
	}
	return result
}

func parseSchedLine(line string) SchedRec {
	if len(line) < 16 {
		line = line + strings.Repeat(" ", 16-len(line))
	} else if len(line) > 16 {
		line = line[:16]
	}
	acct := line[0:4]
	prRaw := line[4:11]
	rateRaw := line[11:15]
	yearsRaw := line[15:16]

	// parse numeric digit strings
	prRaw = strings.TrimSpace(prRaw)
	var pr decimal.Decimal
	if prRaw == "" {
		pr = decimal.NewFromInt(0)
	} else {
		// digits only
		// parse as integer
		n := int64(0)
		for _, c := range prRaw {
			if c >= '0' && c <= '9' {
				n = n*10 + int64(c-'0')
			}
		}
		pr = decimal.New(n, -2)
	}
	rateRaw = strings.TrimSpace(rateRaw)
	var rate decimal.Decimal
	if rateRaw == "" {
		rate = decimal.NewFromInt(0)
	} else {
		n := int64(0)
		for _, c := range rateRaw {
			if c >= '0' && c <= '9' {
				n = n*10 + int64(c-'0')
			}
		}
		rate = decimal.New(n, -2)
	}
	yearsRaw = strings.TrimSpace(yearsRaw)
	var ys int64 = 0
	if yearsRaw != "" {
		for _, c := range yearsRaw {
			if c >= '0' && c <= '9' {
				ys = ys*10 + int64(c-'0')
			}
		}
	}

	return SchedRec{
		ScAcct:  acct,
		ScPrin:  pr,
		ScRate:  rate,
		ScYears: ys,
	}
}

func ReadPara() {
	if schedReader.Scan() {
		line := schedReader.Text()
		curRec = parseSchedLine(line)
		inputDone = false
		WsEofFlag = "N"
	} else {
		schedEOF = true
		inputDone = true
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	// MOVE SC-PRIN TO WS-BAL
	WsBal = curRec.ScPrin.Truncate(2)
	WsBal = storeBal(WsBal)

	for WsYear = 1; WsYear <= curRec.ScYears; WsYear++ {
		// COMPUTE WS-BAL ROUNDED = WS-BAL * (1 + SC-RATE / 100)
		rateDiv := curRec.ScRate.Shift(-2)
		factor := decimal.NewFromInt(1).Add(rateDiv)
		computed := WsBal.Mul(factor)
		rounded := computed.Round(2)
		WsBal = storeBal(rounded)

		WsBalEd = formatBalEd(WsBal)
		// DISPLAY SC-ACCT " Y" WS-YEAR " " WS-BAL-ED
		yearStr := formatIntPic(2, WsYear)
		fmt.Printf("%s Y%s %s\n", curRec.ScAcct, yearStr, WsBalEd)
	}
	WsBalEd = formatBalEd(WsBal)
	fmt.Printf("%s FINAL %s\n", curRec.ScAcct, WsBalEd)
	WsCount = WsCount + 1
	// overflow for WsCount PIC 99
	if WsCount > 99 {
		WsCount = WsCount % 100
	}
	ReadPara()
}

func MainPara() {
	var err error
	schedFile, err = os.Open("input.dat")
	if err != nil {
		// If file not found, treat as empty
		schedFile = nil
		schedEOF = true
		inputDone = true
		WsEofFlag = "Y"
	} else {
		schedReader = bufio.NewScanner(schedFile)
		// Allow long lines
		buf := make([]byte, 0, 64*1024)
		schedReader.Buffer(buf, 1024*1024)
		ReadPara()
		for !inputDone {
			ProcessPara()
		}
		schedFile.Close()
	}
	countStr := formatIntPic(2, WsCount)
	fmt.Printf("SCHEDULES: %s\n", countStr)
}

func main() {
	MainPara()
}
